1	package numeric
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync/atomic"
11		"time"
12	)
13	
14	// recordVersion 是落盘记录格式的版本标记。
15	const recordVersion = "numeric-job-v1"
16	
17	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
18	type storedJob struct {
19		id           uint64
20		submitter    string
21		requestID    string
22		seed         int64
23		values       []int64
24		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
25	
26		queuedAt   time.Time
27		startedAt  time.Time
28		finishedAt time.Time
29	
30		status        Status
31		failureReason string
32		blockerID     uint64
33	
34		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
35		effectiveValues []int64
36		archive         *Archive
37	
38		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
39		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
40		canceled atomic.Bool
41	}
42	
43	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
44	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
45	type jobRecord struct {
46		Version string `json:"version"`
47	
48		ID            uint64  `json:"id"`
49		Submitter     string  `json:"submitter"`
50		RequestID     string  `json:"request_id"`
51		Seed          int64   `json:"seed"`
52		Values        []int64 `json:"values"`
53		HasDependency bool    `json:"has_dependency"`
54		DependencyID  uint64  `json:"dependency_id"`
55		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
56		// 恢复时由 HasDependency/DependencyID 推导。
57		Dependencies []uint64 `json:"dependencies,omitempty"`
58	
59		QueuedAt   time.Time `json:"queued_at"`
60		StartedAt  time.Time `json:"started_at,omitempty"`
61		FinishedAt time.Time `json:"finished_at,omitempty"`
62	
63		Status        Status `json:"status"`
64		FailureReason string `json:"failure_reason,omitempty"`
65		BlockerID     uint64 `json:"blocker_id,omitempty"`
66	
67		EffectiveValues []int64  `json:"effective_values,omitempty"`
68		Archive         *Archive `json:"archive,omitempty"`
69	}
70	
71	func jobFileName(id uint64) string {
72		return fmt.Sprintf("job-%020d.json", id)
73	}
74	
75	func (s *Store) jobPath(j *storedJob) string {
76		return filepath.Join(s.dir, jobFileName(j.id))
77	}
78	
79	func encodeRecord(j *storedJob) ([]byte, error) {
80		r := jobRecord{
81			Version: recordVersion,
82	
83			ID:            j.id,
84			Submitter:     j.submitter,
85			RequestID:     j.requestID,
86			Seed:          j.seed,
87			Values:        append([]int64(nil), j.values...),
88			HasDependency: len(j.dependencies) > 0,
89			DependencyID:  depID(j),
90			Dependencies:  append([]uint64(nil), j.dependencies...),
91	
92			QueuedAt:      j.queuedAt,
93			StartedAt:     j.startedAt,
94			FinishedAt:    j.finishedAt,
95			Status:        j.status,
96			FailureReason: j.failureReason,
97			BlockerID:     j.blockerID,
98	
99			EffectiveValues: append([]int64(nil), j.effectiveValues...),
100			Archive:         j.archive,
101		}
102		return json.MarshalIndent(&r, "", "  ")
103	}
104	
105	// depID 返回首个直接上游作业号（无依赖时为 0）。
106	func depID(j *storedJob) uint64 {
107		if len(j.dependencies) == 0 {
108			return 0
109		}
110		return j.dependencies[0]
111	}
112	
113	// persist 在已持锁的情况下原子写一条作业记录。
114	func (s *Store) persist(j *storedJob) error {
115		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
116		if s.persistFault != nil {
117			if err := s.persistFault(j); err != nil {
118				return err
119			}
120		}
121		data, err := encodeRecord(j)
122		if err != nil {
123			return err
124		}
125		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
126	}
127	
128	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
129	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
130	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
131		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
132		if err != nil {
133			return err
134		}
135		tmpName := tmp.Name()
136		cleanup := true
137		defer func() {
138			if cleanup {
139				_ = os.Remove(tmpName)
140			}
141		}()
142	
143		if _, err := tmp.Write(data); err != nil {
144			_ = tmp.Close()
145			return err
146		}
147		if err := tmp.Sync(); err != nil {
148			_ = tmp.Close()
149			return err
150		}
151		if err := tmp.Close(); err != nil {
152			return err
153		}
154		if err := os.Chmod(tmpName, perm); err != nil {
155			return err
156		}
157		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
158			return err
159		}
160		cleanup = false
161		syncDir(dir)
162		return nil
163	}
164	
165	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
166	func syncDir(dir string) {
167		if d, err := os.Open(dir); err == nil {
168			_ = d.Sync()
169			_ = d.Close()
170		}
171	}
172	
173	// loadDir 扫描目录中的全部作业记录并重建内存索引。
174	//
175	// 恢复规则：
176	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
177	//   - 成功记录缺少归档或校验值对不上时 fail-closed 地标记为失败，
178	//     维持“成功必有完整归档”的不变量。
179	func loadDir(dir string) ([]*storedJob, uint64, error) {
180		entries, err := os.ReadDir(dir)
181		if err != nil {
182			return nil, 0, err
183		}
184		var jobs []*storedJob
185		var maxID uint64
186		for _, e := range entries {
187			name := e.Name()
188			if e.IsDir() {
189				continue
190			}
191			// 清理上一进程崩溃时可能残留的原子写临时文件。
192			if strings.HasPrefix(name, ".tmp-") {
193				_ = os.Remove(filepath.Join(dir, name))
194				continue
195			}
196			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
197				continue
198			}
199			path := filepath.Join(dir, name)
200			data, err := os.ReadFile(path)
201			if err != nil {
202				return nil, 0, err
203			}
204			var r jobRecord
205			if err := json.Unmarshal(data, &r); err != nil {
206				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
207			}
208			if r.Version != recordVersion {
209				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
210			}
211			switch r.Status {
212			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
213			default:
214				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
215			}
216			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
217			// 恢复为只含一个作业号的列表（语义与提交时一致）。
218			deps := append([]uint64(nil), r.Dependencies...)
219			if len(deps) == 0 && r.HasDependency {
220				deps = []uint64{r.DependencyID}
221			}
222			j := &storedJob{
223				id:           r.ID,
224				submitter:    r.Submitter,
225				requestID:    r.RequestID,
226				seed:         r.Seed,
227				values:       append([]int64(nil), r.Values...),
228				dependencies: deps,
229	
230				queuedAt:   r.QueuedAt,
231				startedAt:  r.StartedAt,
232				finishedAt: r.FinishedAt,
233	
234				status:        r.Status,
235				failureReason: r.FailureReason,
236				blockerID:     r.BlockerID,
237	
238				effectiveValues: append([]int64(nil), r.EffectiveValues...),
239				archive:         r.Archive,
240			}
241			if j.status == StatusRunning {
242				j.status = StatusFailed
243				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
244				j.blockerID = 0
245				if j.finishedAt.IsZero() {
246					j.finishedAt = time.Now().UTC()
247				}
248				j.effectiveValues = nil
249				j.archive = nil
250				// 就地重写恢复后的终态。
251				if data, err := encodeRecord(j); err == nil {
252					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
253				}
254			}
255			if j.status == StatusSucceeded && !archiveIntact(j) {
256				j.status = StatusFailed
257				j.failureReason = "归档不完整或校验值不一致，成功结果不可用"
258				if j.finishedAt.IsZero() {
259					j.finishedAt = time.Now().UTC()
260				}
261				j.effectiveValues = nil
262				j.archive = nil
263				if data, err := encodeRecord(j); err == nil {
264					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
265				}
266			}
267			jobs = append(jobs, j)
268			if j.id > maxID {
269				maxID = j.id
270			}
271		}
272		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
273		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
274		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
275		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
276		// 依赖链在单趟级联扫描中漏掉失败传播）。
277		sort.Slice(jobs, func(a, b int) bool {
278			return jobs[a].id < jobs[b].id
279		})
280		return jobs, maxID, nil
281	}
282	
283	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
284	func archiveIntact(j *storedJob) bool {
285		a := j.archive
286		if a == nil {
287			return false
288		}
289		// 归档中的原始参数必须与记录顶层字段一致。
290		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
291			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
292			return false
293		}
294		if a.HasDependency && a.DependencyID != depID(j) {
295			return false
296		}
297		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
298		// 由单依赖字段推导后再比较。
299		aDeps := append([]uint64(nil), a.Dependencies...)
300		if len(aDeps) == 0 && a.HasDependency {
301			aDeps = []uint64{a.DependencyID}
302		}
303		if len(aDeps) != len(j.dependencies) {
304			return false
305		}
306		for i := range j.dependencies {
307			if aDeps[i] != j.dependencies[i] {
308				return false
309			}
310		}
311		if len(a.Values) != len(j.values) {
312			return false
313		}
314		for i := range j.values {
315			if a.Values[i] != j.values[i] {
316				return false
317			}
318		}
319		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
320			return false
321		}
322		for i := range j.effectiveValues {
323			if j.effectiveValues[i] != a.EffectiveValues[i] {
324				return false
325			}
326		}
327		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
328			return false
329		}
330		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
331			return false
332		}
333		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
334			return false
335		}
336		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
337			return false
338		}
339		return true
340	}
