1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	type Store struct {
32		dir string
33	
34		mu     sync.Mutex
35		jobs   []*storedJob // 严格按作业号（即提交先后）排列
36		byID   map[uint64]*storedJob
37		idem   map[string]uint64 // submitter\x00requestID -> 作业号
38		nextID uint64
39		closed bool
40	
41		now func() time.Time
42	
43		runningID uint64
44		waitCh    chan struct{}
45		stopCh    chan struct{}
46		stopping  atomic.Bool
47		wg        sync.WaitGroup
48	
49		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
50		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
51		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
52		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
53	
54		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
55		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
56		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
57		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
58		persistFault func(j *storedJob) error
59	}
60	
61	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
62	//
63	// 恢复语义：
64	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
65	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
66	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
67	//   - 成功状态始终与完整归档同时可见。
68	func Open(dir string, opts ...Option) (*Store, error) {
69		if err := os.MkdirAll(dir, 0o700); err != nil {
70			return nil, err
71		}
72		jobs, maxID, err := loadDir(dir)
73		if err != nil {
74			return nil, err
75		}
76		s := &Store{
77			dir:    dir,
78			jobs:   jobs,
79			byID:   make(map[uint64]*storedJob),
80			idem:   make(map[string]uint64),
81			nextID: maxID + 1,
82			now:    wallClock{}.Now,
83			waitCh: make(chan struct{}, 1),
84			stopCh: make(chan struct{}),
85		}
86		for _, opt := range opts {
87			opt(s)
88		}
89		for _, j := range jobs {
90			s.byID[j.id] = j
91			if j.requestID != "" {
92				s.idem[s.idemKey(j.submitter, j.requestID)] = j.id
93			}
94		}
95		// 重建失败/取消作业对排队下游的阻断。
96		s.cascadeLocked()
97		s.wg.Add(1)
98		go s.worker()
99		return s, nil
100	}
101	
102	func (s *Store) idemKey(submitter, requestID string) string {
103		return submitter + "\x00" + requestID
104	}
105	
106	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
107	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
108	func (s *Store) Close() error {
109		s.mu.Lock()
110		if s.closed {
111			s.mu.Unlock()
112			return nil
113		}
114		s.closed = true
115		var running *storedJob
116		if s.runningID != 0 {
117			running = s.byID[s.runningID]
118		}
119		s.mu.Unlock()
120	
121		if s.stopping.CompareAndSwap(false, true) {
122			close(s.stopCh)
123		}
124		// 中止正在运行的计算。
125		if running != nil {
126			running.canceled.Store(true)
127		}
128		s.notify()
129		s.wg.Wait()
130		return nil
131	}
132	
133	// Submit 接受一次作业提交。
134	//
135	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
136	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
137	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
138	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
139	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
140		s.mu.Lock()
141		defer s.mu.Unlock()
142		if s.closed || s.stopping.Load() {
143			return nil, ErrStoreClosed
144		}
145		if len(req.Values) == 0 {
146			return nil, ErrEmptySequence
147		}
148		if err := s.validateDependenciesLocked(&req); err != nil {
149			return nil, err
150		}
151		deps := requestDeps(&req)
152		if req.RequestID != "" {
153			key := s.idemKey(req.Submitter, req.RequestID)
154			if origID, ok := s.idem[key]; ok {
155				orig := s.byID[origID]
156				if sameContent(orig, &req) {
157					return s.viewLocked(orig), nil
158				}
159				return s.viewLocked(orig),
160					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
161						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
162			}
163		}
164	
165		now := s.now().UTC()
166		j := &storedJob{
167			id:           s.nextID,
168			submitter:    req.Submitter,
169			requestID:    req.RequestID,
170			seed:         req.Seed,
171			values:       append([]int64(nil), req.Values...),
172			dependencies: append([]uint64(nil), deps...),
173			queuedAt:     now,
174			status:       StatusQueued,
175		}
176		// 先持久化，接受之后该提交即不可丢失。
177		if err := s.persist(j); err != nil {
178			return nil, err
179		}
180		s.nextID++
181		s.jobs = append(s.jobs, j)
182		s.byID[j.id] = j
183		if req.RequestID != "" {
184			s.idem[s.idemKey(req.Submitter, req.RequestID)] = j.id
185		}
186		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
187		s.cascadeLocked()
188		s.notifyLocked()
189		return s.viewLocked(j), nil
190	}
191	
192	// requestDeps 规范化一次提交的直接上游作业号列表：
193	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
194	// 两者皆无则为 nil。调用前须先经 [Store.validateDependenciesLocked] 校验。
195	func requestDeps(req *SubmitRequest) []uint64 {
196		if len(req.Dependencies) > 0 {
197			return append([]uint64(nil), req.Dependencies...)
198		}
199		if req.HasDependency {
200			return []uint64{req.DependencyID}
201		}
202		return nil
203	}
204	
205	// validateDependenciesLocked 在持锁状态下校验提交的依赖列表：
206	//   - 单依赖方式与非空列表同时启用 → 拒绝；
207	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）；
208	//   - 列表引用提交时不存在的作业 → 拒绝。
209	//
210	// 任一拒绝都不产生记录，也不占用幂等请求号。
211	func (s *Store) validateDependenciesLocked(req *SubmitRequest) error {
212		if req.HasDependency && len(req.Dependencies) > 0 {
213			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
214		}
215		deps := requestDeps(req)
216		seen := make(map[uint64]struct{}, len(deps))
217		for _, id := range deps {
218			if id == 0 {
219				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
220			}
221			if _, dup := seen[id]; dup {
222				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
223			}
224			seen[id] = struct{}{}
225		}
226		for _, id := range deps {
227			if s.byID[id] == nil {
228				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
229			}
230		}
231		return nil
232	}
233	
234	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
235	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
236	func sameContent(j *storedJob, req *SubmitRequest) bool {
237		if j.seed != req.Seed {
238			return false
239		}
240		rd := requestDeps(req)
241		if len(j.dependencies) != len(rd) {
242			return false
243		}
244		for i := range j.dependencies {
245			if j.dependencies[i] != rd[i] {
246				return false
247			}
248		}
249		if len(j.values) != len(req.Values) {
250			return false
251		}
252		for i := range j.values {
253			if j.values[i] != req.Values[i] {
254				return false
255			}
256		}
257		return true
258	}
259	
260	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
261	func (s *Store) Get(id uint64) (*Job, error) {
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		j := s.byID[id]
265		if j == nil {
266			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
267		}
268		return s.viewLocked(j), nil
269	}
270	
271	// Cancel 请求取消作业。
272	//
273	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
274	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
275	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
276	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
277	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
278	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
279	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
280	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
281	func (s *Store) Cancel(id uint64) (*Job, error) {
282		s.mu.Lock()
283		defer s.mu.Unlock()
284		if s.closed {
285			return nil, ErrStoreClosed
286		}
287		j := s.byID[id]
288		if j == nil {
289			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
290		}
291		switch j.status {
292		case StatusCanceled:
293			return s.viewLocked(j), nil
294		case StatusSucceeded, StatusFailed:
295			return s.viewLocked(j),
296				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
297		}
298	
299		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
300		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
301		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
302		// 不能把这次取消当作已完成。
303		now := s.now().UTC()
304		prevStatus := j.status
305		prevFinishedAt := j.finishedAt
306		prevReason := j.failureReason
307		prevBlocker := j.blockerID
308		prevEffective := j.effectiveValues
309		prevArchive := j.archive
310		j.status = StatusCanceled
311		j.failureReason = ""
312		j.blockerID = 0
313		if j.finishedAt.IsZero() {
314			j.finishedAt = now
315		}
316		j.effectiveValues = nil
317		j.archive = nil
318		if err := s.persist(j); err != nil {
319			j.status = prevStatus
320			j.finishedAt = prevFinishedAt
321			j.failureReason = prevReason
322			j.blockerID = prevBlocker
323			j.effectiveValues = prevEffective
324			j.archive = prevArchive
325			return nil, err
326		}
327	
328		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
329		j.canceled.Store(true)
330		// 依赖它的等待者一并失败，且继续向更下游传播。
331		s.cascadeLocked()
332		s.notifyLocked()
333		return s.viewLocked(j), nil
334	}
335	
336	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
337	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
338	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
339		s.mu.Lock()
340		defer s.mu.Unlock()
341		if !start.IsZero() && !end.IsZero() && start.After(end) {
342			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
343				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
344		}
345		out := make([]*Job, 0)
346		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
347			if j.submitter != submitter {
348				continue
349			}
350			if !start.IsZero() && j.queuedAt.Before(start) {
351				continue
352			}
353			if !end.IsZero() && j.queuedAt.After(end) {
354				continue
355			}
356			out = append(out, s.viewLocked(j))
357		}
358		return out, nil
359	}
360	
361	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
362	//
363	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
364	// 扫描即可让阻断沿链条传播到最下游。作业有多个直接上游时，按列表顺序
365	// 选取最靠前的已失败/取消者作为直接阻断者；作业一旦失败，其原因不再被
366	// 后来发生的上游状态变化改写。
367	func (s *Store) cascadeLocked() {
368		for _, j := range s.jobs {
369			if j.status != StatusQueued || len(j.dependencies) == 0 {
370				continue
371			}
372			var direct *storedJob
373			for _, id := range j.dependencies {
374				dep := s.byID[id]
375				if dep == nil {
376					continue
377				}
378				if dep.status == StatusFailed || dep.status == StatusCanceled {
379					direct = dep
380					break
381				}
382			}
383			if direct == nil {
384				continue
385			}
386			root := direct.blockerID
387			if root == 0 {
388				root = direct.id
389			}
390			s.markFailedLocked(j, blockedReason(direct, root), root)
391		}
392	}
393	
394	func blockedReason(dep *storedJob, root uint64) string {
395		state := "失败"
396		if dep.status == StatusCanceled {
397			state = "被取消"
398		}
399		reason := fmt.Sprintf("直接上游作业 %d 已%s，阻断本作业继续计算", dep.id, state)
400		if dep.status == StatusFailed && dep.failureReason != "" {
401			reason += "（其失败原因：" + dep.failureReason + "）"
402		}
403		if root != dep.id {
404			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
405		}
406		return reason
407	}
408	
409	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
410	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
411	// 该作业就被跳过，不挡住后面可运行的作业。
412	func (s *Store) pickRunnableLocked() *storedJob {
413		for _, j := range s.jobs {
414			if j.status != StatusQueued {
415				continue
416			}
417			if len(j.dependencies) == 0 {
418				return j
419			}
420			ready := true
421			for _, id := range j.dependencies {
422				dep := s.byID[id]
423				if dep == nil || dep.status != StatusSucceeded {
424					ready = false
425					break
426				}
427			}
428			if ready {
429				return j
430			}
431		}
432		return nil
433	}
434	
435	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
436	func (s *Store) notifyLocked() {
437		select {
438		case s.waitCh <- struct{}{}:
439		default:
440		}
441	}
442	
443	// notify 在不持锁时唤醒 worker。
444	func (s *Store) notify() {
445		s.mu.Lock()
446		s.notifyLocked()
447		s.mu.Unlock()
448	}
449	
450	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
451	func (s *Store) persistRetry(j *storedJob, attempts int) error {
452		var err error
453		for i := 0; i < attempts; i++ {
454			if err = s.persist(j); err == nil {
455				return nil
456			}
457		}
458		return err
459	}
460	
461	// worker 是本地唯一的计算执行体。
462	func (s *Store) worker() {
463		defer s.wg.Done()
464		for {
465			s.mu.Lock()
466			if s.stopping.Load() {
467				s.mu.Unlock()
468				return
469			}
470			j := s.pickRunnableLocked()
471			if j == nil {
472				ch := s.waitCh
473				s.mu.Unlock()
474				select {
475				case <-ch:
476				case <-s.stopCh:
477				}
478				continue
479			}
480	
481			// 进入运行并原子持久化该状态。
482			j.status = StatusRunning
483			j.startedAt = s.now().UTC()
484			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
485			inputs := append([]int64(nil), j.values...)
486			for _, id := range j.dependencies {
487				if dep := s.byID[id]; dep != nil && dep.archive != nil {
488					inputs = append(inputs, dep.archive.Sum)
489				}
490			}
491			seed := j.seed
492			s.runningID = j.id
493			if err := s.persistRetry(j, 3); err != nil {
494				// 连运行状态都无法落盘：保守地失败，不进行计算。
495				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
496				s.runningID = 0
497				s.cascadeLocked()
498				s.notifyLocked()
499				s.mu.Unlock()
500				continue
501			}
502			s.mu.Unlock()
503	
504			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
505			doCompute := s.compute
506			if doCompute == nil {
507				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
508					return computeResult(in, sd, c)
509				}
510			}
511			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
512	
513			s.mu.Lock()
514			s.runningID = 0
515			switch {
516			case j.status == StatusCanceled:
517				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
518				j.archive = nil
519				j.effectiveValues = nil
520				_ = s.persistRetry(j, 3)
521				s.cascadeLocked()
522			case s.stopping.Load():
523				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
524				s.cascadeLocked()
525			case !ok:
526				s.markFailedLocked(j, reason, 0)
527				s.cascadeLocked()
528			default:
529				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
530				completed := s.now().UTC()
531				a := newArchive(j, inputs, sum, sumSq, completed)
532				j.effectiveValues = append([]int64(nil), inputs...)
533				j.status = StatusSucceeded
534				j.finishedAt = completed
535				j.failureReason = ""
536				j.blockerID = 0
537				j.archive = a
538				if err := s.persistRetry(j, 3); err != nil {
539					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
540					j.archive = nil
541					j.effectiveValues = nil
542					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
543					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
544					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
545					s.cascadeLocked()
546				}
547			}
548			s.notifyLocked()
549			s.mu.Unlock()
550		}
551	}
552	
553	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
554	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
555		j.status = StatusFailed
556		j.failureReason = reason
557		j.blockerID = blocker
558		if j.finishedAt.IsZero() {
559			j.finishedAt = s.now().UTC()
560		}
561		j.archive = nil
562		j.effectiveValues = nil
563		_ = s.persistRetry(j, 3)
564	}
565	
566	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
567	// 上游作业号只作记录，不参与任何摘要与校验值。
568	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
569		inDigest := inputsDigestHex(effective, j.seed)
570		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
571		log := buildLog(effective, j.seed, sum, sumSquares)
572		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
573		var firstDep uint64
574		if len(j.dependencies) > 0 {
575			firstDep = j.dependencies[0]
576		}
577		return &Archive{
578			JobID:           j.id,
579			Submitter:       j.submitter,
580			RequestID:       j.requestID,
581			Seed:            j.seed,
582			Values:          append([]int64(nil), j.values...),
583			HasDependency:   len(j.dependencies) > 0,
584			DependencyID:    firstDep,
585			Dependencies:    append([]uint64(nil), j.dependencies...),
586			EffectiveValues: append([]int64(nil), effective...),
587			InputsDigest:    inDigest,
588			Sum:             sum,
589			SumOfSquares:    sumSquares,
590			ResultDigest:    resDigest,
591			Log:             log,
592			Checksum:        checksum,
593			CompletedAt:     completedAt,
594		}
595	}
596	
597	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
598	func (s *Store) viewLocked(j *storedJob) *Job {
599		v := &Job{
600			ID:              j.id,
601			Submitter:       j.submitter,
602			RequestID:       j.requestID,
603			Seed:            j.seed,
604			Values:          append([]int64(nil), j.values...),
605			Dependencies:    append([]uint64(nil), j.dependencies...),
606			QueuedAt:        j.queuedAt,
607			StartedAt:       j.startedAt,
608			FinishedAt:      j.finishedAt,
609			Status:          j.status,
610			FailureReason:   j.failureReason,
611			BlockerID:       j.blockerID,
612			EffectiveValues: append([]int64(nil), j.effectiveValues...),
613		}
614		v.HasDependency = len(j.dependencies) > 0
615		if len(j.dependencies) > 0 {
616			v.DependencyID = j.dependencies[0]
617		}
618		if j.status == StatusQueued {
619			v.WaitReason = WaitSlot
620			// 列出尚未成功归档的直接上游，保持提交时的顺序。
621			for _, id := range j.dependencies {
622				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
623					v.PendingDependencies = append(v.PendingDependencies, id)
624				}
625			}
626			if len(v.PendingDependencies) > 0 {
627				v.WaitReason = WaitDependency
628			}
629		}
630		if j.archive != nil {
631			a := *j.archive
632			a.Values = append([]int64(nil), j.archive.Values...)
633			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
634			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
635			v.Archive = &a
636		}
637		return v
638	}
639	
640	// Dir 返回归档目录路径。
641	func (s *Store) Dir() string { return s.dir }
642

