	// 内容变化 → 冲突，保留原记录。
	j, err := s2.Submit(SubmitRequest{Submitter: "u", RequestID: "k1", Values: []int64{2, 1}, Seed: 3})
	if !errors.Is(err, ErrIdempotencyConflict) || j == nil || j.ID != orig.ID {
