1	package numeric
2	
3	import (
4		"errors"
5		"strings"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// manualClock 是确定性时钟：每次取值自动推进，保证提交时间严格可排序。
12	type manualClock struct {
13		mu sync.Mutex
14		t  time.Time
15	}
16	
17	func newManualClock() *manualClock {
18		return &manualClock{t: time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)}
19	}
20	
21	func (c *manualClock) Now() time.Time {
22		c.mu.Lock()
23		defer c.mu.Unlock()
24		c.t = c.t.Add(time.Microsecond)
25		return c.t
26	}
27	
28	func openTestStore(t *testing.T) (*Store, *manualClock) {
29		t.Helper()
30		clock := newManualClock()
31		s, err := Open(t.TempDir(), WithClock(clock))
32		if err != nil {
33			t.Fatalf("open: %v", err)
34		}
35		t.Cleanup(func() { _ = s.Close() })
36		return s, clock
37	}
38	
39	func waitStatus(t *testing.T, s *Store, id uint64, want Status) *Job {
40		t.Helper()
41		deadline := time.Now().Add(5 * time.Second)
42		for {
43			j, err := s.Get(id)
44			if err != nil {
45				t.Fatalf("get %d: %v", id, err)
46			}
47			if j.Status == want {
48				return j
49			}
50			if isTerminal(j.Status) && want != j.Status {
51				t.Fatalf("job %d reached terminal %s (reason=%q), want %s",
52					id, j.Status, j.FailureReason, want)
53			}
54			if time.Now().After(deadline) {
55				t.Fatalf("job %d status=%s, want %s (reason=%q)", id, j.Status, want, j.FailureReason)
56			}
57			time.Sleep(time.Millisecond)
58		}
59	}
60	
61	func isTerminal(st Status) bool {
62		return st == StatusSucceeded || st == StatusFailed || st == StatusCanceled
63	}
64	
65	func mustSubmit(t *testing.T, s *Store, req SubmitRequest) *Job {
66		t.Helper()
67		j, err := s.Submit(req)
68		if err != nil {
69			t.Fatalf("submit: %v", err)
70		}
71		return j
72	}
73	
74	// gateCompute 安装计算钩子：block(id) 让指定作业停在“计算中”，
75	// release(id) 放行；未 block 的作业直接完成。started 记录进入计算的作业号，
76	// order 记录实际完成计算的顺序，计算本身仍由真实 computeResult 完成。
77	func gateCompute(t *testing.T, s *Store) (
78		started chan uint64,
79		block func(ids ...uint64),
80		release func(id uint64),
81		order *[]uint64,
82		omu *sync.Mutex,
83	) {
84		t.Helper()
85		started = make(chan uint64, 64)
86		var bmu sync.Mutex
87		gates := make(map[uint64]chan struct{})
88		var ord []uint64
89		omu = &sync.Mutex{}
90		block = func(ids ...uint64) {
91			bmu.Lock()
92			defer bmu.Unlock()
93			for _, id := range ids {
94				gates[id] = make(chan struct{})
95			}
96		}
97		release = func(id uint64) {
98			bmu.Lock()
99			ch, ok := gates[id]
100			bmu.Unlock()
101			if ok {
102				close(ch)
103			}
104		}
105		s.compute = func(id uint64, inputs []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
106			started <- id
107			bmu.Lock()
108			ch := gates[id]
109			bmu.Unlock()
110			if ch != nil {
111				select {
112				case <-ch:
113				case <-s.stopCh: // Close 时自动放行，真实计算随后观察到取消而中止
114				}
115			}
116			omu.Lock()
117			ord = append(ord, id)
118			omu.Unlock()
119			return computeResult(inputs, seed, canceled)
120		}
121		return started, block, release, &ord, omu
122	}
123	
124	func waitStarted(t *testing.T, started <-chan uint64, want uint64) {
125		t.Helper()
126		select {
127		case id := <-started:
128			if id != want {
129				t.Fatalf("expected job %d to start, got %d", want, id)
130			}
131		case <-time.After(5 * time.Second):
132			t.Fatalf("job %d did not start", want)
133		}
134	}
135	
136	func TestSubmitRejectsEmptySequence(t *testing.T) {
137		s, _ := openTestStore(t)
138		_, err := s.Submit(SubmitRequest{Submitter: "a", RequestID: "r1", Values: nil})
139		if !errors.Is(err, ErrEmptySequence) {
140			t.Fatalf("err=%v, want ErrEmptySequence", err)
141		}
142		_, err = s.Submit(SubmitRequest{Submitter: "a", RequestID: "r1", Values: []int64{}})
143		if !errors.Is(err, ErrEmptySequence) {
144			t.Fatalf("err=%v, want ErrEmptySequence", err)
145		}
146		// 不产生任何记录。
147		if got, _ := s.List("a", time.Time{}, time.Time{}); len(got) != 0 {
148			t.Fatalf("empty submit created records: %d", len(got))
149		}
150	}
151	
152	func TestSubmitDependencyMustExist(t *testing.T) {
153		s, _ := openTestStore(t)
154		_, err := s.Submit(SubmitRequest{
155			Submitter: "a", RequestID: "r1", Values: []int64{1},
156			HasDependency: true, DependencyID: 999,
157		})
158		if !errors.Is(err, ErrDependencyNotFound) {
159			t.Fatalf("err=%v, want ErrDependencyNotFound", err)
160		}
161		if _, err := s.Get(1); !errors.Is(err, ErrNotFound) {
162			t.Fatalf("rejected dependency submit left a record: %v", err)
163		}
164	}
165	
166	func TestBasicSuccessAndArchive(t *testing.T) {
167		s, _ := openTestStore(t)
168		j := mustSubmit(t, s, SubmitRequest{
169			Submitter: "alice", RequestID: "req-1", Values: []int64{1, 2, 3, -4}, Seed: 7,
170		})
171		if j.ID != 1 || j.Status != StatusQueued {
172			t.Fatalf("initial view: %+v", j)
173		}
174		done := waitStatus(t, s, 1, StatusSucceeded)
175		a := done.Archive
176		if a == nil {
177			t.Fatal("succeeded job has no archive")
178		}
179		if a.Sum != 2 || a.SumOfSquares != 30 {
180			t.Fatalf("results sum=%d sq=%d, want 2,30", a.Sum, a.SumOfSquares)
181		}
182		wantEffective := []int64{1, 2, 3, -4}
183		if len(a.EffectiveValues) != 4 || a.EffectiveValues[3] != -4 {
184			t.Fatalf("effective=%v", a.EffectiveValues)
185		}
186		if a.InputsDigest != inputsDigestHex(wantEffective, 7) ||
187			a.ResultDigest != resultDigestHex(wantEffective, 7, 2, 30) ||
188			a.Checksum != checksumHex(wantEffective, 7, 2, 30, a.Log, a.ResultDigest) {
189			t.Fatal("archive digests/checksum mismatch")
190		}
191		if a.Submitter != "alice" || a.RequestID != "req-1" || a.Seed != 7 {
192			t.Fatal("original params not archived")
193		}
194		if a.CompletedAt.IsZero() {
195			t.Fatal("CompletedAt missing")
196		}
197	}
198	
199	func TestDigestIndependentOfIDAndTime(t *testing.T) {
200		s1, c1 := openTestStore(t)
201		s2, _ := openTestStore(t)
202		_ = c1
203		mustSubmit(t, s1, SubmitRequest{Submitter: "a", Values: []int64{5, -2}, Seed: 3})
204		// 在另一个目录、不同时间、不同作业号下提交完全相同的有效输入与种子。
205		time.Sleep(5 * time.Millisecond)
206		mustSubmit(t, s2, SubmitRequest{Submitter: "b", Values: []int64{5, -2}, Seed: 3})
207		a := waitStatus(t, s1, 1, StatusSucceeded).Archive
208		b := waitStatus(t, s2, 1, StatusSucceeded).Archive
209		if a.ResultDigest != b.ResultDigest || a.Checksum != b.Checksum || a.InputsDigest != b.InputsDigest {
210			t.Fatal("digests/checksum must be independent of submitter, job id and time")
211		}
212		if a.Log != b.Log {
213			t.Fatal("log must be identical for identical effective inputs+seed")
214		}
215		if a.CompletedAt.Equal(b.CompletedAt) {
216			// 极小概率；用不同目录时钟时几乎不可能相等。
217			// CompletedAt 允许不同，不参与摘要。
218		}
219	}
