232		}
233	}
234	
235	func TestIdempotencyConflictKeepsOriginal(t *testing.T) {
236		s, _ := openTestStore(t)
237		orig := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "k", Values: []int64{1, 2}, Seed: 0})
238		waitStatus(t, s, orig.ID, StatusSucceeded)
239	
240		variants := []SubmitRequest{
241			{Submitter: "a", RequestID: "k", Values: []int64{2, 1}, Seed: 0}, // 次序变化
242			{Submitter: "a", RequestID: "k", Values: []int64{1, 2}, Seed: 9}, // 种子变化
243			{Submitter: "a", RequestID: "k", Values: []int64{1, 2, 3}, Seed: 0},
244		}
245		for i, v := range variants {
246			j, err := s.Submit(v)
247			if !errors.Is(err, ErrIdempotencyConflict) {
248				t.Fatalf("variant %d: err=%v, want conflict", i, err)
249			}
250			if j == nil || j.ID != orig.ID {
251				t.Fatalf("variant %d: conflict must also return original job", i)
252			}
253		}
254		// 依赖变化也是冲突：先造一个可引用的作业 5。
255		dep := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "dep", Values: []int64{1}})
256		waitStatus(t, s, dep.ID, StatusSucceeded)
257		_, err := s.Submit(SubmitRequest{
258			Submitter: "a", RequestID: "k", Values: []int64{1, 2}, Seed: 0,
259			HasDependency: true, DependencyID: dep.ID,
260		})
261		if !errors.Is(err, ErrIdempotencyConflict) {
262			t.Fatalf("dependency change err=%v, want conflict", err)
263		}
264		// 原记录结果不变。
265		got := waitStatus(t, s, orig.ID, StatusSucceeded)
266		if got.Archive == nil || got.Archive.Sum != 3 {
267			t.Fatal("original record altered after conflicts")
268		}
269	}
