370	func TestDependencyWaitDoesNotBlockRunnableJobs(t *testing.T) {
371		s, _ := openTestStore(t)
372		started, block, release, _, _ := gateCompute(t, s)
373		block(1)
374	
375		first := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}}) // id 1 占住位置
376		waitStarted(t, started, first.ID)
377	
378		waiting := mustSubmit(t, s, SubmitRequest{ // id 2 等 id 1 的结果
379			Submitter: "a", Values: []int64{2},
380			HasDependency: true, DependencyID: first.ID,
381		})
382		runnable := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{3}}) // id 3 无依赖
383	
384		// 唯一位置正被 id 1 占用：id 2 说明在等依赖结果，id 3 说明在等计算位置。
385		if j, _ := s.Get(waiting.ID); j.WaitReason != WaitDependency {
386			t.Fatalf("waiting job reason=%q, want WaitDependency", j.WaitReason)
387		}
