// 含零字符的标识仍分别指向各自原来的作业号；重放不创建额外记录，且记录
// 加载次序不影响索引指向。已成功归档的参数、摘要与校验值不得被改写。
func TestNULIdempotencyKeysSurviveReopen(t *testing.T) {
	dir := t.TempDir()
